class Employee {
  + id : int
  + name : string
  + address : string
}

class AssemblyService {
  + kms : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class Part {
  + category : string
  + serialNumber : string
  + price : float
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + id : int
  + name : string
  + address : string
  + phone : string
}

class CarModelCompatibility {
}

Employee "1" -- "*" AssemblyService : responsibleFor
AssemblyService "*" -- "1" Car : executedOn
AssemblyService "*" -- "1..*" Part : fits
Part "*" -- "*" Car : fitsInModel
Car "*" -- "1" Owner : ownedBy

@enduml

